#!/usr/bin/env bash
# ship-ios.sh — archive, export and upload the Chronolog iOS shell to TestFlight.
#
# Ported from ~/sites/timeConvertor/scripts/ship.sh (itself from musicLibrary's
# ship-naviadmin.sh). The differences come from Tauri:
#
# - The Xcode project is src-tauri/gen/apple (generated by `tauri ios init`, committed). Its
#   "Build Rust Code" phase calls back into a running Tauri CLI, so a bare `xcodebuild archive`
#   fails ("failed to read missing addr file …-server-addr"). The archive and export are
#   therefore done by `tauri ios build --export-method app-store-connect`, which runs
#   xcodebuild build → archive → -exportArchive with gen/apple/ExportOptions.plist (copied
#   from scripts/ios/ExportOptions.plist before each run).
# - The build number lives in src-tauri/tauri.ios.conf.json (bundle.iOS.bundleVersion): Tauri
#   rewrites Info.plist from its config on every build. See lib/version.sh.
# - Tauri passes -allowProvisioningUpdates and this Mac's Xcode is signed in to the developer
#   account. Release signing is therefore Manual in gen/apple/project.yml (Apple Distribution +
#   "Chronolog App Store" profile, build keychain via OTHER_CODE_SIGN_FLAGS), so Xcode never
#   creates App IDs or profiles on its own: a missing profile is a hard error.
#
# Usage:
#   scripts/ios/ship-ios.sh <new-build-number> [--skip-upload]
#   scripts/ios/ship-ios.sh --help
#
# Steps:
#   1. Source api-key.env and unlock the build keychain
#   2. Preflight: Apple Distribution identity and the "Chronolog App Store" profile installed
#      (SKIP_PREFLIGHT=1 continues anyway, to see Xcode's own signing error)
#   3. Bump bundle.iOS.bundleVersion in tauri.ios.conf.json (monotonic)
#   4. Archive + export via `tauri ios build --export-method app-store-connect`
#   5. Assert the archive embeds the bumped build number, version and bundle id; find the .ipa
#   6. Upload with `xcrun altool --upload-app` (skipped with --skip-upload or SKIP_UPLOAD=1)
#   7. Summary, and a row in docs/IOS-RELEASE.md's release log
#
# A run that stops before the upload (failure, or --skip-upload) puts the build number back, so
# a dry run leaves tauri.ios.conf.json unchanged.

set -euo pipefail

SCRIPTS_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_DIR="$(cd "$SCRIPTS_DIR/../.." && pwd)"
TAURI_DIR="$REPO_DIR/src-tauri"
APPLE_DIR="$TAURI_DIR/gen/apple"
IOS_CONFIG="$TAURI_DIR/tauri.ios.conf.json"
BUILD_DIR="$APPLE_DIR/build"
SIGNING_DIR="$HOME/sites/navidromClient/spike/.signing"
KEYCHAIN="$HOME/Library/Keychains/spike-build.keychain-db"
PRODUCT_NAME="Chronolog"
BUNDLE_ID="dev.thisolivier.chronolog"
TEAM_ID="CNHB9B5GX6"
PROFILE_NAME="Chronolog App Store"
ARCHIVE_PATH="$BUILD_DIR/chronolog_iOS.xcarchive"
RELEASE_LOG="$REPO_DIR/docs/IOS-RELEASE.md"

usage() {
  echo "Usage: $0 <new-build-number> [--skip-upload]"
  echo ""
  echo "Bumps the iOS build number, archives and exports Chronolog with tauri ios build,"
  echo "and uploads the .ipa to TestFlight with altool."
  echo ""
  echo "Prerequisites (docs/IOS-RELEASE.md):"
  echo "  - Xcode with the iOS SDK; rustup targets aarch64-apple-ios(-sim); npm install done"
  echo "  - $SIGNING_DIR populated (api-key.env, keychain.password)"
  echo "  - Build keychain at $KEYCHAIN with the Apple Distribution identity"
  echo "  - App ID $BUNDLE_ID and an App Store Connect record (owner, one-time)"
  echo "  - '$PROFILE_NAME' profile installed in ~/Library/MobileDevice/Provisioning Profiles/"
  echo ""
  echo "  --skip-upload   Run steps 1-5 and print the altool command instead of running it."
  echo "                  SKIP_UPLOAD=1 has the same effect. The build number is put back."
  echo "  SKIP_PREFLIGHT=1  Continue past a missing identity/profile (to see Xcode's error)."
  echo ""
  echo "Example: $0 1"
  exit "${1:-0}"
}

step() { echo ""; echo "=== $1 ==="; }
fail() { echo "FAILED at step: $1"; exit 1; }

# shellcheck source=lib/version.sh
source "$SCRIPTS_DIR/lib/version.sh"

SKIP_UPLOAD="${SKIP_UPLOAD:-0}"
SKIP_PREFLIGHT="${SKIP_PREFLIGHT:-0}"

[[ "${1:-}" == "--help" || "${1:-}" == "-h" ]] && usage 0
[[ $# -eq 0 ]] && usage 1

NEW_BUILD_NUMBER="$1"
shift || true

while [[ $# -gt 0 ]]; do
  case "$1" in
    --skip-upload) SKIP_UPLOAD=1 ;;
    *) echo "Error: unknown argument '$1'"; usage 1 ;;
  esac
  shift
done

if ! [[ "$NEW_BUILD_NUMBER" =~ ^[0-9]+$ ]]; then
  echo "Error: build number must be a positive integer, got '$NEW_BUILD_NUMBER'"
  exit 1
fi

# Put the build number back if the run ends before the upload step (see the header)
PREVIOUS_BUILD_NUMBER=""
KEEP_BUILD_NUMBER=0
restore_build_number() {
  if [[ -n "$PREVIOUS_BUILD_NUMBER" && "$KEEP_BUILD_NUMBER" != "1" ]]; then
    node -e '
      const fs = require("fs");
      const [path, buildNumber] = process.argv.slice(1);
      const config = JSON.parse(fs.readFileSync(path, "utf8"));
      config.bundle.iOS.bundleVersion = buildNumber;
      fs.writeFileSync(path, JSON.stringify(config, null, 2) + "\n");
    ' "$IOS_CONFIG" "$PREVIOUS_BUILD_NUMBER"
    echo "(bundle.iOS.bundleVersion put back to $PREVIOUS_BUILD_NUMBER)"
  fi
}
trap restore_build_number EXIT

# ------------------------------------------------------------------
step "1/7 Source API key + unlock keychain"

[[ -f "$SIGNING_DIR/api-key.env" ]] || { echo "Error: $SIGNING_DIR/api-key.env not found"; exit 1; }
# shellcheck disable=SC1091
source "$SIGNING_DIR/api-key.env"

[[ -f "$SIGNING_DIR/keychain.password" ]] || { echo "Error: $SIGNING_DIR/keychain.password not found"; exit 1; }
# The build keychain auto-locks after 6h; unlocking an unlocked keychain is harmless.
security unlock-keychain -p "$(cat "$SIGNING_DIR/keychain.password")" "$KEYCHAIN" 2>/dev/null || true
echo "Keychain unlocked, API key id loaded (${#APPSTORE_KEY_ID} characters)"

# ------------------------------------------------------------------
step "2/7 Preflight: signing identity and profile"

PREFLIGHT_PROBLEMS=0
if security find-identity -v -p codesigning "$KEYCHAIN" | grep -q "Apple Distribution: .*($TEAM_ID)"; then
  echo "OK  Apple Distribution identity for $TEAM_ID in the build keychain"
else
  echo "MISSING  Apple Distribution identity for $TEAM_ID in $KEYCHAIN"
  PREFLIGHT_PROBLEMS=1
fi

# A profile counts when its Name matches and its App ID is TEAM.BUNDLE_ID
find_profile() {
  local directory profile
  for directory in "$HOME/Library/MobileDevice/Provisioning Profiles" "$HOME/Library/Developer/Xcode/UserData/Provisioning Profiles"; do
    [[ -d "$directory" ]] || continue
    for profile in "$directory"/*.mobileprovision; do
      [[ -f "$profile" ]] || continue
      local decoded
      decoded="$(security cms -D -i "$profile" 2>/dev/null)" || continue
      if [[ "$(plutil -extract Name raw -o - - <<<"$decoded" 2>/dev/null)" == "$PROFILE_NAME" ]] &&
         [[ "$(plutil -extract Entitlements.application-identifier raw -o - - <<<"$decoded" 2>/dev/null)" == "$TEAM_ID.$BUNDLE_ID" ]]; then
        echo "$profile"
        return 0
      fi
    done
  done
  return 1
}

if PROFILE_PATH="$(find_profile)"; then
  echo "OK  '$PROFILE_NAME' for $TEAM_ID.$BUNDLE_ID: $PROFILE_PATH"
else
  echo "MISSING  '$PROFILE_NAME' provisioning profile for $TEAM_ID.$BUNDLE_ID"
  PREFLIGHT_PROBLEMS=1
fi

if [[ "$PREFLIGHT_PROBLEMS" == "1" ]]; then
  echo ""
  echo "One-time owner steps (docs/IOS-RELEASE.md, 'One-time setup'):"
  echo "  1. developer.apple.com → Identifiers → +: App ID, explicit bundle id $BUNDLE_ID"
  echo "  2. appstoreconnect.apple.com → Apps → +: new iOS app 'Chronolog', bundle id $BUNDLE_ID"
  echo "  3. developer.apple.com → Profiles → +: App Store Connect, App ID $BUNDLE_ID,"
  echo "     the Apple Distribution certificate, named exactly '$PROFILE_NAME'"
  echo "  4. Install it: copy to $SIGNING_DIR and to"
  echo "     ~/Library/MobileDevice/Provisioning Profiles/<UUID>.mobileprovision"
  if [[ "$SKIP_PREFLIGHT" == "1" ]]; then
    echo "SKIP_PREFLIGHT=1 — continuing so Xcode reports what it needs."
  else
    fail "preflight (set SKIP_PREFLIGHT=1 to continue to the archive anyway)"
  fi
fi

# ------------------------------------------------------------------
step "3/7 Bump build number"

PREVIOUS_BUILD_NUMBER="$(read_build_number "$IOS_CONFIG")"
bump_build_number "$IOS_CONFIG" "$NEW_BUILD_NUMBER"
MARKETING_VERSION="$(read_marketing_version "$REPO_DIR/package.json")"
echo "Version $MARKETING_VERSION ($NEW_BUILD_NUMBER)"

# ------------------------------------------------------------------
step "4/7 Archive + export (tauri ios build)"

# A stale archive or .ipa from an earlier run would pass the checks below and ship an old binary
rm -rf "$BUILD_DIR"
cp "$SCRIPTS_DIR/ExportOptions.plist" "$APPLE_DIR/ExportOptions.plist"

BUILD_LOG="$(mktemp -t chronolog-ios-build)"
echo "Full log: $BUILD_LOG"
if ! ( cd "$REPO_DIR" && CI=true npx tauri ios build --export-method app-store-connect ) >"$BUILD_LOG" 2>&1; then
  grep -E "error:|Error |\\*\\* (BUILD|ARCHIVE|EXPORT) FAILED" "$BUILD_LOG" | grep -v "^    export " | tail -8 || tail -20 "$BUILD_LOG"
  fail "archive/export (tauri ios build)"
fi
tail -3 "$BUILD_LOG"

# ------------------------------------------------------------------
step "5/7 Verify archive and .ipa"

[[ -d "$ARCHIVE_PATH" ]] || fail "archive (xcarchive not found at $ARCHIVE_PATH)"
ARCHIVE_INFO_PLIST="$ARCHIVE_PATH/Products/Applications/$PRODUCT_NAME.app/Info.plist"
read_archive_key() { /usr/libexec/PlistBuddy -c "Print :$1" "$ARCHIVE_INFO_PLIST" 2>/dev/null || echo "unreadable"; }
ARCHIVED_BUILD="$(read_archive_key CFBundleVersion)"
ARCHIVED_VERSION="$(read_archive_key CFBundleShortVersionString)"
ARCHIVED_BUNDLE_ID="$(read_archive_key CFBundleIdentifier)"
[[ "$ARCHIVED_BUILD" == "$NEW_BUILD_NUMBER" ]] || fail "archive (CFBundleVersion is '$ARCHIVED_BUILD', expected '$NEW_BUILD_NUMBER')"
[[ "$ARCHIVED_VERSION" == "$MARKETING_VERSION" ]] || fail "archive (CFBundleShortVersionString is '$ARCHIVED_VERSION', expected '$MARKETING_VERSION')"
[[ "$ARCHIVED_BUNDLE_ID" == "$BUNDLE_ID" ]] || fail "archive (bundle id is '$ARCHIVED_BUNDLE_ID', expected '$BUNDLE_ID')"
echo "Archive OK: $ARCHIVED_BUNDLE_ID $ARCHIVED_VERSION ($ARCHIVED_BUILD)"

IPA_PATH="$(find "$BUILD_DIR" -name "*.ipa" -type f | head -1)"
[[ -n "$IPA_PATH" && -f "$IPA_PATH" ]] || fail "export (no .ipa under $BUILD_DIR)"
echo "Export OK: $IPA_PATH"

# ------------------------------------------------------------------
step "6/7 Upload to TestFlight"

if [[ "$SKIP_UPLOAD" == "1" ]]; then
  echo "SKIP_UPLOAD set — not calling 'xcrun altool --upload-app'. Would have run:"
  echo "  xcrun altool --upload-app -f \"$IPA_PATH\" -t ios --apiKey \"\$APPSTORE_KEY_ID\" --apiIssuer \"\$APPSTORE_ISSUER_ID\""
  DELIVERY_UUID="(skipped)"
else
  # From here on the build number may be consumed by App Store Connect: keep the bump
  KEEP_BUILD_NUMBER=1
  # `|| true` so a nonzero altool exit reaches the check below instead of aborting the
  # assignment under set -e and hiding Apple's validation errors (seen in timeConvertor).
  UPLOAD_OUTPUT=$(xcrun altool --upload-app \
    -f "$IPA_PATH" \
    -t ios \
    --apiKey "$APPSTORE_KEY_ID" \
    --apiIssuer "$APPSTORE_ISSUER_ID" 2>&1) || true
  echo "$UPLOAD_OUTPUT"
  echo "$UPLOAD_OUTPUT" | grep -q 'UPLOAD SUCCEEDED' || fail "upload"
  DELIVERY_UUID=$(echo "$UPLOAD_OUTPUT" | grep 'Delivery UUID:' | sed 's/.*Delivery UUID: //')
fi

# ------------------------------------------------------------------
step "7/7 Summary"

COMMIT_SHA=$(git -C "$REPO_DIR" rev-parse --short HEAD 2>/dev/null || echo "unknown")
if [[ "$SKIP_UPLOAD" != "1" ]]; then
  echo "| $(date +%F) | $NEW_BUILD_NUMBER | $MARKETING_VERSION | $COMMIT_SHA | delivery $DELIVERY_UUID |" >>"$RELEASE_LOG"
  echo "Recorded in docs/IOS-RELEASE.md. Commit it with src-tauri/tauri.ios.conf.json and gen/apple."
fi

echo ""
echo "Ship complete!"
echo "  Version:       $MARKETING_VERSION ($NEW_BUILD_NUMBER)"
echo "  Delivery UUID: $DELIVERY_UUID"
echo "  Commit:        $COMMIT_SHA"
echo ""
echo "A Delivery UUID is NOT a delivered build: App Store Connect processing is asynchronous and"
echo "can still end INVALID or FAILED. Check before telling anyone the build is up:"
echo "  ~/sites/musicLibrary/iOSnative/scripts/asc-builds.py $BUNDLE_ID   (expect processingState VALID)"
